// Activation tokens on Wayland: see activation.h.
#include "activation.h"
#include "pointerlock.h"

#include <QGuiApplication>
#include <QtGui/qguiapplication_platform.h>

#include <cstring>
#include <wayland-client.h>

// The protocol's code (generated by wayland-scanner from the XML beside it;
// cpp/wayland/README). (About the pragma: see pointerlock.cpp.)
extern "C" {
#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wattributes"
#include "wayland/xdg-activation-v1-protocol.c"
#pragma GCC diagnostic pop
#include "wayland/xdg-activation-v1-client-protocol.h"
}

namespace {

struct Request {
    xdg_activation_v1 *activation = nullptr;
    QString token;
};

void global(void *data, wl_registry *registry, uint32_t name, const char *interface, uint32_t)
{
    auto *request = static_cast<Request *>(data);
    if (!request->activation && !strcmp(interface, xdg_activation_v1_interface.name))
        request->activation = static_cast<xdg_activation_v1 *>(wl_registry_bind(registry, name, &xdg_activation_v1_interface, 1));
}
void globalRemove(void *, wl_registry *, uint32_t) {}
const wl_registry_listener s_registryListener = {global, globalRemove};

void done(void *data, xdg_activation_token_v1 *, const char *token)
{
    static_cast<Request *>(data)->token = QString::fromUtf8(token);
}
const xdg_activation_token_v1_listener s_tokenListener = {done};

} // namespace

QString WindowActivation::token()
{
    if (!QGuiApplication::platformName().startsWith(QLatin1String("wayland"))) return {};
    auto *wayland = qGuiApp->nativeInterface<QNativeInterface::QWaylandApplication>();
    if (!wayland || !wayland->display() || !wayland->seat()) return {};

    // On a queue of Kite's own, read here until the answer is in: Qt reads
    // the default one in another thread (as in PointerLock::setUp).
    wl_display *display = wayland->display();
    wl_event_queue *queue = wl_display_create_queue(display);
    auto *wrapped = static_cast<wl_display *>(wl_proxy_create_wrapper(display));
    wl_proxy_set_queue(reinterpret_cast<wl_proxy *>(wrapped), queue);
    wl_registry *registry = wl_display_get_registry(wrapped);
    wl_proxy_wrapper_destroy(wrapped);

    Request request;
    wl_registry_add_listener(registry, &s_registryListener, &request);
    wl_display_roundtrip_queue(display, queue);
    wl_registry_destroy(registry);
    if (request.activation) {
        xdg_activation_token_v1 *asked = xdg_activation_v1_get_activation_token(request.activation);
        xdg_activation_token_v1_add_listener(asked, &s_tokenListener, &request);
        // What the compositor checks the request against: the user's last
        // input, and the window it went to (KWin: the active one).
        xdg_activation_token_v1_set_serial(asked, wayland->lastInputSerial(), wayland->seat());
        if (wl_surface *surface = PointerLock::pointerSurface()) xdg_activation_token_v1_set_surface(asked, surface);
        xdg_activation_token_v1_commit(asked);
        wl_display_roundtrip_queue(display, queue);
        xdg_activation_token_v1_destroy(asked);
        xdg_activation_v1_destroy(request.activation);
    }
    wl_event_queue_destroy(queue);
    return request.token;
}
